class RFST(object):

    # RFST
    def __init__(
        self,
        MATERIAL_ID = None,
        NAME = None,
        MATERIAL_CLASS = 0,
        DESCRIPTION = None,
        FREQUENCY_MIN_MHZ = 0.0,
        FREQUENCY_MAX_MHZ = 0.0,
        PERMITTIVITY_COEFFICIENT_A = 0.0,
        PERMITTIVITY_EXPONENT_B = 0.0,
        CONDUCTIVITY_COEFFICIENT_C = 0.0,
        CONDUCTIVITY_EXPONENT_D = 0.0,
        REFERENCE_FREQUENCY_MHZ = 0.0,
        RELATIVE_PERMITTIVITY_REAL = 0.0,
        RELATIVE_PERMITTIVITY_IMAGINARY = 0.0,
        CONDUCTIVITY_S_PER_M = 0.0,
        LOSS_TANGENT = 0.0,
        RELATIVE_PERMEABILITY_REAL = 0.0,
        RELATIVE_PERMEABILITY_IMAGINARY = 0.0,
        REFLECTIVITY = 0.0,
        REFLECTION_LOSS_DB = 0.0,
        THICKNESS_M = 0.0,
        TRANSMISSION_LOSS_DB = 0.0,
        ATTENUATION_DB_PER_M = 0.0,
        ABSORPTION_COEFFICIENT = 0.0,
        SURFACE_ROUGHNESS_RMS_M = 0.0,
        ROUGHNESS_CORRELATION_LENGTH_M = 0.0,
        SCATTERING_CLASS = 0,
        DIFFUSE_SCATTERING_COEFFICIENT = 0.0,
        BACKSCATTER_COEFFICIENT_DB = 0.0,
        TEMPERATURE_K = 0.0,
        MOISTURE_CONTENT_FRACTION = 0.0,
        SALINITY_PSU = 0.0,
        FREQUENCY_SAMPLES = None,
        REFLECTION_TABLE = None,
        GEOMETRY = None,
        PROVENANCE = None,
        COMPUTED_AT = 0,
        PRODUCER_ID = None,
        SIGNATURE = None,
    ):
        self.MATERIAL_ID = MATERIAL_ID  # type: Optional[str]
        self.NAME = NAME  # type: Optional[str]
        self.MATERIAL_CLASS = MATERIAL_CLASS  # type: int
        self.DESCRIPTION = DESCRIPTION  # type: Optional[str]
        self.FREQUENCY_MIN_MHZ = FREQUENCY_MIN_MHZ  # type: float
        self.FREQUENCY_MAX_MHZ = FREQUENCY_MAX_MHZ  # type: float
        self.PERMITTIVITY_COEFFICIENT_A = PERMITTIVITY_COEFFICIENT_A  # type: float
        self.PERMITTIVITY_EXPONENT_B = PERMITTIVITY_EXPONENT_B  # type: float
        self.CONDUCTIVITY_COEFFICIENT_C = CONDUCTIVITY_COEFFICIENT_C  # type: float
        self.CONDUCTIVITY_EXPONENT_D = CONDUCTIVITY_EXPONENT_D  # type: float
        self.REFERENCE_FREQUENCY_MHZ = REFERENCE_FREQUENCY_MHZ  # type: float
        self.RELATIVE_PERMITTIVITY_REAL = RELATIVE_PERMITTIVITY_REAL  # type: float
        self.RELATIVE_PERMITTIVITY_IMAGINARY = RELATIVE_PERMITTIVITY_IMAGINARY  # type: float
        self.CONDUCTIVITY_S_PER_M = CONDUCTIVITY_S_PER_M  # type: float
        self.LOSS_TANGENT = LOSS_TANGENT  # type: float
        self.RELATIVE_PERMEABILITY_REAL = RELATIVE_PERMEABILITY_REAL  # type: float
        self.RELATIVE_PERMEABILITY_IMAGINARY = RELATIVE_PERMEABILITY_IMAGINARY  # type: float
        self.REFLECTIVITY = REFLECTIVITY  # type: float
        self.REFLECTION_LOSS_DB = REFLECTION_LOSS_DB  # type: float
        self.THICKNESS_M = THICKNESS_M  # type: float
        self.TRANSMISSION_LOSS_DB = TRANSMISSION_LOSS_DB  # type: float
        self.ATTENUATION_DB_PER_M = ATTENUATION_DB_PER_M  # type: float
        self.ABSORPTION_COEFFICIENT = ABSORPTION_COEFFICIENT  # type: float
        self.SURFACE_ROUGHNESS_RMS_M = SURFACE_ROUGHNESS_RMS_M  # type: float
        self.ROUGHNESS_CORRELATION_LENGTH_M = ROUGHNESS_CORRELATION_LENGTH_M  # type: float
        self.SCATTERING_CLASS = SCATTERING_CLASS  # type: int
        self.DIFFUSE_SCATTERING_COEFFICIENT = DIFFUSE_SCATTERING_COEFFICIENT  # type: float
        self.BACKSCATTER_COEFFICIENT_DB = BACKSCATTER_COEFFICIENT_DB  # type: float
        self.TEMPERATURE_K = TEMPERATURE_K  # type: float
        self.MOISTURE_CONTENT_FRACTION = MOISTURE_CONTENT_FRACTION  # type: float
        self.SALINITY_PSU = SALINITY_PSU  # type: float
        self.FREQUENCY_SAMPLES = FREQUENCY_SAMPLES  # type: Optional[List[RFSFrequencySample.RFSFrequencySampleT]]
        self.REFLECTION_TABLE = REFLECTION_TABLE  # type: Optional[List[RFSReflectionEntry.RFSReflectionEntryT]]
        self.GEOMETRY = GEOMETRY  # type: Optional[List[RFSGeometryRef.RFSGeometryRefT]]
        self.PROVENANCE = PROVENANCE  # type: Optional[RFSProvenance.RFSProvenanceT]
        self.COMPUTED_AT = COMPUTED_AT  # type: int
        self.PRODUCER_ID = PRODUCER_ID  # type: Optional[str]
        self.SIGNATURE = SIGNATURE  # type: Optional[List[int]]

    @classmethod
    def InitFromBuf(cls, buf, pos):
        tmpRfs = RFS()
        tmpRfs.Init(buf, pos)
        return cls.InitFromObj(tmpRfs)

    @classmethod
    def InitFromPackedBuf(cls, buf, pos=0):
        n = flatbuffers.encode.Get(flatbuffers.packer.uoffset, buf, pos)
        return cls.InitFromBuf(buf, pos+n)

    @classmethod
    def InitFromObj(cls, tmpRfs):
        x = RFST()
        x._UnPack(tmpRfs)
        return x

    # RFST
    def _UnPack(self, RFS):
        if RFS is None:
            return
        self.MATERIAL_ID = RFS.MATERIAL_ID()
        self.NAME = RFS.NAME()
        self.MATERIAL_CLASS = RFS.MATERIAL_CLASS()
        self.DESCRIPTION = RFS.DESCRIPTION()
        self.FREQUENCY_MIN_MHZ = RFS.FREQUENCY_MIN_MHZ()
        self.FREQUENCY_MAX_MHZ = RFS.FREQUENCY_MAX_MHZ()
        self.PERMITTIVITY_COEFFICIENT_A = RFS.PERMITTIVITY_COEFFICIENT_A()
        self.PERMITTIVITY_EXPONENT_B = RFS.PERMITTIVITY_EXPONENT_B()
        self.CONDUCTIVITY_COEFFICIENT_C = RFS.CONDUCTIVITY_COEFFICIENT_C()
        self.CONDUCTIVITY_EXPONENT_D = RFS.CONDUCTIVITY_EXPONENT_D()
        self.REFERENCE_FREQUENCY_MHZ = RFS.REFERENCE_FREQUENCY_MHZ()
        self.RELATIVE_PERMITTIVITY_REAL = RFS.RELATIVE_PERMITTIVITY_REAL()
        self.RELATIVE_PERMITTIVITY_IMAGINARY = RFS.RELATIVE_PERMITTIVITY_IMAGINARY()
        self.CONDUCTIVITY_S_PER_M = RFS.CONDUCTIVITY_S_PER_M()
        self.LOSS_TANGENT = RFS.LOSS_TANGENT()
        self.RELATIVE_PERMEABILITY_REAL = RFS.RELATIVE_PERMEABILITY_REAL()
        self.RELATIVE_PERMEABILITY_IMAGINARY = RFS.RELATIVE_PERMEABILITY_IMAGINARY()
        self.REFLECTIVITY = RFS.REFLECTIVITY()
        self.REFLECTION_LOSS_DB = RFS.REFLECTION_LOSS_DB()
        self.THICKNESS_M = RFS.THICKNESS_M()
        self.TRANSMISSION_LOSS_DB = RFS.TRANSMISSION_LOSS_DB()
        self.ATTENUATION_DB_PER_M = RFS.ATTENUATION_DB_PER_M()
        self.ABSORPTION_COEFFICIENT = RFS.ABSORPTION_COEFFICIENT()
        self.SURFACE_ROUGHNESS_RMS_M = RFS.SURFACE_ROUGHNESS_RMS_M()
        self.ROUGHNESS_CORRELATION_LENGTH_M = RFS.ROUGHNESS_CORRELATION_LENGTH_M()
        self.SCATTERING_CLASS = RFS.SCATTERING_CLASS()
        self.DIFFUSE_SCATTERING_COEFFICIENT = RFS.DIFFUSE_SCATTERING_COEFFICIENT()
        self.BACKSCATTER_COEFFICIENT_DB = RFS.BACKSCATTER_COEFFICIENT_DB()
        self.TEMPERATURE_K = RFS.TEMPERATURE_K()
        self.MOISTURE_CONTENT_FRACTION = RFS.MOISTURE_CONTENT_FRACTION()
        self.SALINITY_PSU = RFS.SALINITY_PSU()
        if not RFS.FREQUENCY_SAMPLESIsNone():
            self.FREQUENCY_SAMPLES = []
            for i in range(RFS.FREQUENCY_SAMPLESLength()):
                if RFS.FREQUENCY_SAMPLES(i) is None:
                    self.FREQUENCY_SAMPLES.append(None)
                else:
                    rFSFrequencySample_ = RFSFrequencySample.RFSFrequencySampleT.InitFromObj(RFS.FREQUENCY_SAMPLES(i))
                    self.FREQUENCY_SAMPLES.append(rFSFrequencySample_)
        if not RFS.REFLECTION_TABLEIsNone():
            self.REFLECTION_TABLE = []
            for i in range(RFS.REFLECTION_TABLELength()):
                if RFS.REFLECTION_TABLE(i) is None:
                    self.REFLECTION_TABLE.append(None)
                else:
                    rFSReflectionEntry_ = RFSReflectionEntry.RFSReflectionEntryT.InitFromObj(RFS.REFLECTION_TABLE(i))
                    self.REFLECTION_TABLE.append(rFSReflectionEntry_)
        if not RFS.GEOMETRYIsNone():
            self.GEOMETRY = []
            for i in range(RFS.GEOMETRYLength()):
                if RFS.GEOMETRY(i) is None:
                    self.GEOMETRY.append(None)
                else:
                    rFSGeometryRef_ = RFSGeometryRef.RFSGeometryRefT.InitFromObj(RFS.GEOMETRY(i))
                    self.GEOMETRY.append(rFSGeometryRef_)
        if RFS.PROVENANCE() is not None:
            self.PROVENANCE = RFSProvenance.RFSProvenanceT.InitFromObj(RFS.PROVENANCE())
        self.COMPUTED_AT = RFS.COMPUTED_AT()
        self.PRODUCER_ID = RFS.PRODUCER_ID()
        if not RFS.SIGNATUREIsNone():
            if np is None:
                self.SIGNATURE = []
                for i in range(RFS.SIGNATURELength()):
                    self.SIGNATURE.append(RFS.SIGNATURE(i))
            else:
                self.SIGNATURE = RFS.SIGNATUREAsNumpy()

    # RFST
    def Pack(self, builder):
        if self.MATERIAL_ID is not None:
            MATERIAL_ID = builder.CreateString(self.MATERIAL_ID)
        if self.NAME is not None:
            NAME = builder.CreateString(self.NAME)
        if self.DESCRIPTION is not None:
            DESCRIPTION = builder.CreateString(self.DESCRIPTION)
        if self.FREQUENCY_SAMPLES is not None:
            FREQUENCY_SAMPLESlist = []
            for i in range(len(self.FREQUENCY_SAMPLES)):
                FREQUENCY_SAMPLESlist.append(self.FREQUENCY_SAMPLES[i].Pack(builder))
            RFSStartFREQUENCY_SAMPLESVector(builder, len(self.FREQUENCY_SAMPLES))
            for i in reversed(range(len(self.FREQUENCY_SAMPLES))):
                builder.PrependUOffsetTRelative(FREQUENCY_SAMPLESlist[i])
            FREQUENCY_SAMPLES = builder.EndVector()
        if self.REFLECTION_TABLE is not None:
            REFLECTION_TABLElist = []
            for i in range(len(self.REFLECTION_TABLE)):
                REFLECTION_TABLElist.append(self.REFLECTION_TABLE[i].Pack(builder))
            RFSStartREFLECTION_TABLEVector(builder, len(self.REFLECTION_TABLE))
            for i in reversed(range(len(self.REFLECTION_TABLE))):
                builder.PrependUOffsetTRelative(REFLECTION_TABLElist[i])
            REFLECTION_TABLE = builder.EndVector()
        if self.GEOMETRY is not None:
            GEOMETRYlist = []
            for i in range(len(self.GEOMETRY)):
                GEOMETRYlist.append(self.GEOMETRY[i].Pack(builder))
            RFSStartGEOMETRYVector(builder, len(self.GEOMETRY))
            for i in reversed(range(len(self.GEOMETRY))):
                builder.PrependUOffsetTRelative(GEOMETRYlist[i])
            GEOMETRY = builder.EndVector()
        if self.PROVENANCE is not None:
            PROVENANCE = self.PROVENANCE.Pack(builder)
        if self.PRODUCER_ID is not None:
            PRODUCER_ID = builder.CreateString(self.PRODUCER_ID)
        if self.SIGNATURE is not None:
            if np is not None and type(self.SIGNATURE) is np.ndarray:
                SIGNATURE = builder.CreateNumpyVector(self.SIGNATURE)
            else:
                RFSStartSIGNATUREVector(builder, len(self.SIGNATURE))
                for i in reversed(range(len(self.SIGNATURE))):
                    builder.PrependUint8(self.SIGNATURE[i])
                SIGNATURE = builder.EndVector()
        RFSStart(builder)
        if self.MATERIAL_ID is not None:
            RFSAddMATERIAL_ID(builder, MATERIAL_ID)
        if self.NAME is not None:
            RFSAddNAME(builder, NAME)
        RFSAddMATERIAL_CLASS(builder, self.MATERIAL_CLASS)
        if self.DESCRIPTION is not None:
            RFSAddDESCRIPTION(builder, DESCRIPTION)
        RFSAddFREQUENCY_MIN_MHZ(builder, self.FREQUENCY_MIN_MHZ)
        RFSAddFREQUENCY_MAX_MHZ(builder, self.FREQUENCY_MAX_MHZ)
        RFSAddPERMITTIVITY_COEFFICIENT_A(builder, self.PERMITTIVITY_COEFFICIENT_A)
        RFSAddPERMITTIVITY_EXPONENT_B(builder, self.PERMITTIVITY_EXPONENT_B)
        RFSAddCONDUCTIVITY_COEFFICIENT_C(builder, self.CONDUCTIVITY_COEFFICIENT_C)
        RFSAddCONDUCTIVITY_EXPONENT_D(builder, self.CONDUCTIVITY_EXPONENT_D)
        RFSAddREFERENCE_FREQUENCY_MHZ(builder, self.REFERENCE_FREQUENCY_MHZ)
        RFSAddRELATIVE_PERMITTIVITY_REAL(builder, self.RELATIVE_PERMITTIVITY_REAL)
        RFSAddRELATIVE_PERMITTIVITY_IMAGINARY(builder, self.RELATIVE_PERMITTIVITY_IMAGINARY)
        RFSAddCONDUCTIVITY_S_PER_M(builder, self.CONDUCTIVITY_S_PER_M)
        RFSAddLOSS_TANGENT(builder, self.LOSS_TANGENT)
        RFSAddRELATIVE_PERMEABILITY_REAL(builder, self.RELATIVE_PERMEABILITY_REAL)
        RFSAddRELATIVE_PERMEABILITY_IMAGINARY(builder, self.RELATIVE_PERMEABILITY_IMAGINARY)
        RFSAddREFLECTIVITY(builder, self.REFLECTIVITY)
        RFSAddREFLECTION_LOSS_DB(builder, self.REFLECTION_LOSS_DB)
        RFSAddTHICKNESS_M(builder, self.THICKNESS_M)
        RFSAddTRANSMISSION_LOSS_DB(builder, self.TRANSMISSION_LOSS_DB)
        RFSAddATTENUATION_DB_PER_M(builder, self.ATTENUATION_DB_PER_M)
        RFSAddABSORPTION_COEFFICIENT(builder, self.ABSORPTION_COEFFICIENT)
        RFSAddSURFACE_ROUGHNESS_RMS_M(builder, self.SURFACE_ROUGHNESS_RMS_M)
        RFSAddROUGHNESS_CORRELATION_LENGTH_M(builder, self.ROUGHNESS_CORRELATION_LENGTH_M)
        RFSAddSCATTERING_CLASS(builder, self.SCATTERING_CLASS)
        RFSAddDIFFUSE_SCATTERING_COEFFICIENT(builder, self.DIFFUSE_SCATTERING_COEFFICIENT)
        RFSAddBACKSCATTER_COEFFICIENT_DB(builder, self.BACKSCATTER_COEFFICIENT_DB)
        RFSAddTEMPERATURE_K(builder, self.TEMPERATURE_K)
        RFSAddMOISTURE_CONTENT_FRACTION(builder, self.MOISTURE_CONTENT_FRACTION)
        RFSAddSALINITY_PSU(builder, self.SALINITY_PSU)
        if self.FREQUENCY_SAMPLES is not None:
            RFSAddFREQUENCY_SAMPLES(builder, FREQUENCY_SAMPLES)
        if self.REFLECTION_TABLE is not None:
            RFSAddREFLECTION_TABLE(builder, REFLECTION_TABLE)
        if self.GEOMETRY is not None:
            RFSAddGEOMETRY(builder, GEOMETRY)
        if self.PROVENANCE is not None:
            RFSAddPROVENANCE(builder, PROVENANCE)
        RFSAddCOMPUTED_AT(builder, self.COMPUTED_AT)
        if self.PRODUCER_ID is not None:
            RFSAddPRODUCER_ID(builder, PRODUCER_ID)
        if self.SIGNATURE is not None:
            RFSAddSIGNATURE(builder, SIGNATURE)
        RFS = RFSEnd(builder)
        return RFS
